// ===== lib/util.js =====

/**
 * Small shared helpers: IDs, config coercion, and the HMAC scheme that lets n8n
 * trust a webhook came from the dashboard.
 */

/**
 * n8n's Code sandbox only exposes built-ins when NODE_FUNCTION_ALLOW_BUILTIN is
 * set. IDs degrade to Math.random without it; HMAC cannot, so it fails with a
 * config error rather than pretending to verify anything.
 */
let crypto = null;
try { crypto = require('crypto'); } catch (_e) { crypto = null; }

/** Unambiguous alphabet — no 0/O/1/I/L, because these get read aloud and retyped. */
const ID_ALPHABET = '23456789ABCDEFGHJKMNPQRSTUVWXYZ';

const defaultRand = () => (crypto ? crypto.randomBytes(1)[0] / 256 : Math.random());

function randomId(length = 6, rand = defaultRand) {
  let out = '';
  for (let i = 0; i < length; i++) out += ID_ALPHABET[Math.floor(rand() * ID_ALPHABET.length) % ID_ALPHABET.length];
  return out;
}

/** APP-20260814-K7M2QX — sortable by eye, unique enough for this volume. */
function makeApplicantId(date = new Date(), rand) {
  const d = date.toISOString().slice(0, 10).replace(/-/g, '');
  return `APP-${d}-${randomId(6, rand)}`;
}

/** One per workflow execution. Ties rows, log lines, and errors together. */
function makeCorrelationId(workflow = 'WF', date = new Date(), rand) {
  const t = date.toISOString().replace(/[-:TZ.]/g, '').slice(0, 14);
  return `${workflow}-${t}-${randomId(4, rand)}`;
}

function nowIso(date = new Date()) { return date.toISOString(); }

function truthy(v) {
  if (typeof v === 'boolean') return v;
  return ['true', 'yes', '1', 'y', 'on'].includes(String(v == null ? '' : v).trim().toLowerCase());
}

/**
 * Turn the Config tab's rows into a typed object.
 * Unknown types fall through as strings rather than throwing — a bad `type`
 * cell should not take the pipeline down.
 */
function parseConfig(rows) {
  const out = {};
  for (const r of rows || []) {
    const key = String(r.key || '').trim();
    if (!key) continue;
    const raw = r.value == null ? '' : String(r.value);
    switch (String(r.type || 'string').trim().toLowerCase()) {
      case 'boolean': out[key] = truthy(raw); break;
      case 'number': { const n = Number(raw); out[key] = Number.isFinite(n) ? n : 0; break; }
      case 'list': out[key] = raw.split(',').map((s) => s.trim()).filter(Boolean); break;
      case 'json': try { out[key] = JSON.parse(raw); } catch (_e) { out[key] = null; } break;
      default: out[key] = raw;
    }
  }
  return out;
}

/** Chunk a list so batches respect Sheets write limits and model rate limits. */
function chunk(items, size) {
  const out = [];
  const n = Math.max(1, Number(size) || 1);
  for (let i = 0; i < (items || []).length; i += n) out.push(items.slice(i, i + n));
  return out;
}

/** Google Sheets caps a cell at 50k characters; truncate visibly, never silently. */
const CELL_LIMIT = 49000;
function fitCell(value) {
  const s = value == null ? '' : String(value);
  return s.length <= CELL_LIMIT ? s : s.slice(0, CELL_LIMIT) + '\n<!-- truncated for sheet cell limit -->';
}

// --- Webhook signing --------------------------------------------------------

/**
 * The dashboard signs `${timestamp}.${body}`; n8n recomputes and compares.
 * Timestamp is inside the signed payload so a captured request cannot be
 * replayed outside the tolerance window.
 */
function requireCrypto() {
  if (!crypto) {
    throw new Error('E-CONFIG-MISSING: node:crypto is unavailable in this sandbox. Set NODE_FUNCTION_ALLOW_BUILTIN=crypto on the n8n container — webhook signatures cannot be verified without it.');
  }
  return crypto;
}

/**
 * Recursively key-sorted JSON. The dashboard serialises an object, n8n parses
 * it and re-serialises to verify; without canonicalisation any key-order
 * difference across that hop would look like tampering.
 */
function canonicalJson(value) {
  if (value === null || typeof value !== 'object') return JSON.stringify(value ?? null);
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(',')}]`;
  const keys = Object.keys(value).sort();
  return `{${keys.map((k) => `${JSON.stringify(k)}:${canonicalJson(value[k])}`).join(',')}}`;
}

function signPayload(secret, body, timestamp) {
  requireCrypto();
  const ts = String(timestamp);
  const payload = typeof body === 'string' ? body : canonicalJson(body);
  const mac = crypto.createHmac('sha256', String(secret)).update(`${ts}.${payload}`).digest('hex');
  return { signature: `v1=${mac}`, timestamp: ts };
}

function verifySignature(secret, body, timestamp, signature, { toleranceSec = 300, now = Date.now() } = {}) {
  requireCrypto();
  if (!secret) return { ok: false, reason: 'no-secret-configured' };
  if (!signature || !timestamp) return { ok: false, reason: 'missing-signature' };

  const age = Math.abs(now / 1000 - Number(timestamp));
  if (!Number.isFinite(age)) return { ok: false, reason: 'bad-timestamp' };
  if (age > toleranceSec) return { ok: false, reason: 'stale-timestamp' };

  const expected = signPayload(secret, body, timestamp).signature;
  const a = Buffer.from(expected);
  const b = Buffer.from(String(signature));
  if (a.length !== b.length) return { ok: false, reason: 'bad-signature' };
  return crypto.timingSafeEqual(a, b) ? { ok: true } : { ok: false, reason: 'bad-signature' };
}

// ===== lib/intake.js =====

/**
 * Intake validation and normalisation (WF-01).
 *
 * Deliberately pure: no I/O, no clock, no randomness unless injected. Every
 * rejection produces a typed code, never a silent drop — a blocked row is
 * visible in the dashboard with a reason attached.
 */


/**
 * Pragmatic email check. Deliberately not RFC 5322: the goal is to catch typos
 * and empty cells, not to litigate quoted local parts. Anything that passes
 * here still has to survive the mail server.
 */
const EMAIL_RE = /^[^\s@,;:<>()[\]\\]+@[^\s@.]+(\.[^\s@.]+)+$/;

function normaliseEmail(raw) {
  return String(raw == null ? '' : raw).trim().toLowerCase();
}

function isValidEmail(raw) {
  const e = normaliseEmail(raw);
  return e.length > 0 && e.length <= 254 && EMAIL_RE.test(e);
}

function normaliseName(raw) {
  return String(raw == null ? '' : raw).replace(/\s+/g, ' ').trim();
}

/** Keep digits and a single leading +; blank rather than guess. */
function normalisePhone(raw) {
  const s = String(raw == null ? '' : raw).trim();
  if (!s) return '';
  const plus = s.startsWith('+') ? '+' : '';
  const digits = s.replace(/\D/g, '');
  return digits ? plus + digits : '';
}

/** Case- and whitespace-insensitive key for matching roles and categories. */
function slug(raw) {
  return String(raw == null ? '' : raw).trim().toLowerCase().replace(/[\s_]+/g, '-').replace(/[^a-z0-9-]/g, '');
}

/**
 * Pull a Google Drive file ID out of the many link shapes Drive hands out.
 * Returns '' for non-Drive URLs — those are fetched over plain HTTP instead.
 */
function extractDriveFileId(url) {
  const s = String(url == null ? '' : url).trim();
  if (!s) return '';
  const patterns = [
    /\/file\/d\/([a-zA-Z0-9_-]{10,})/,      // /file/d/<id>/view
    /[?&]id=([a-zA-Z0-9_-]{10,})/,          // ?id=<id>
    /\/document\/d\/([a-zA-Z0-9_-]{10,})/,  // Docs
    /\/open\?id=([a-zA-Z0-9_-]{10,})/,
  ];
  for (const re of patterns) {
    const m = s.match(re);
    if (m) return m[1];
  }
  return '';
}

function isHttpUrl(url) {
  const s = String(url == null ? '' : url).trim();
  return /^https?:\/\/[^\s]+$/i.test(s);
}

/** Deterministic dedupe key: one application per person per role. */
function dedupeKey(email, jobRole) {
  return `${normaliseEmail(email)}::${slug(jobRole)}`;
}

/**
 * Validate and normalise one raw intake row.
 *
 * @param {object} raw            row as read from the sheet or form webhook
 * @param {object} ctx
 * @param {string[]} ctx.roles        titles from the JobRoles tab
 * @param {string[]} ctx.categories   allowed categories from Config
 * @param {Set<string>} [ctx.seen]    dedupe keys already present
 * @param {string} ctx.correlationId
 * @param {string} ctx.applicantId    pre-minted id (injected, so this stays pure)
 * @param {string} ctx.now            ISO timestamp (injected)
 * @returns {{ok: true, row: object} | {ok: false, error: AppError, row: object}}
 */
function validateIntake(raw, ctx) {
  const { roles = [], categories = [], seen = new Set(), correlationId = '', applicantId = '', now = '' } = ctx || {};

  const name = normaliseName(raw.name);
  const email = normaliseEmail(raw.email);
  const jobRole = normaliseName(raw.job_role);
  const category = normaliseName(raw.category);
  const resumeLink = String(raw.resume_link == null ? '' : raw.resume_link).trim();

  const base = {
    applicant_id: raw.applicant_id || applicantId,
    created_at: raw.created_at || now,
    name,
    email,
    phone: normalisePhone(raw.phone),
    job_role: jobRole,
    category,
    resume_link: resumeLink,
    resume_file_id: extractDriveFileId(resumeLink),
    source: raw.source || 'manual',
    stage: STAGE.NEW,
    status: STATUS.OK,
    email_status: 'none',
    reply_state: 'none',
    error_code: '',
    error_message: '',
    correlation_id: correlationId,
    updated_at: now,
  };

  const fail = (code, message, details) => ({
    ok: false,
    error: new AppError(code, message, details),
    row: { ...base, stage: STAGE.NEW, status: STATUS.BLOCKED },
  });

  // Order matters: report the most actionable problem first.
  const missing = [];
  if (!name) missing.push('name');
  if (!email) missing.push('email');
  if (!jobRole) missing.push('job_role');
  if (missing.length) {
    return fail('E-INTAKE-MISSING', `Required field(s) empty: ${missing.join(', ')}.`, { missing });
  }

  if (!isValidEmail(email)) {
    return fail('E-INTAKE-EMAIL', `"${email}" is not a valid email address.`, {});
  }

  if (roles.length) {
    const match = roles.find((r) => slug(r) === slug(jobRole));
    if (!match) {
      return fail('E-INTAKE-ROLE', `Job role "${jobRole}" is not in the JobRoles tab.`, { known: roles.slice(0, 20) });
    }
    base.job_role = match; // snap to canonical casing so grouping is exact
  }

  if (category && categories.length) {
    const match = categories.find((c) => slug(c) === slug(category));
    if (!match) {
      return fail('E-INTAKE-CATEGORY', `Category "${category}" is not allowed. Allowed: ${categories.join(', ')}.`, { categories });
    }
    base.category = match;
  }

  if (resumeLink && !isHttpUrl(resumeLink)) {
    return fail('E-FETCH-TYPE', `resume_link is not an http(s) URL: "${resumeLink.slice(0, 80)}".`, {});
  }

  const key = dedupeKey(base.email, base.job_role);
  if (seen.has(key)) {
    return fail('E-INTAKE-DUPE', `${base.email} already has an application for "${base.job_role}".`, { key });
  }

  return { ok: true, row: base, key };
}

// ===== lib/template.js =====

/**
 * Template selection, merge-field rendering, and HTML sanity checks (WF-02/03).
 *
 * The hard rule enforced here: an email with an unresolved {{merge_field}} is
 * never sendable. It fails as E-MAIL-TEMPLATE before it reaches Gmail, because
 * "Hi {{name}}," reaching a candidate is worse than a visible error.
 */

const FIELD_RE = /\{\{\s*([a-zA-Z0-9_.]+)\s*\}\}/g;

/** Void elements never need a closing tag. */
const VOID_TAGS = new Set(['area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link', 'meta', 'param', 'source', 'track', 'wbr', '!doctype']);

/** Escape a value destined for an HTML email body. */
function escapeHtml(value) {
  return String(value == null ? '' : value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

/** Every {{field}} referenced by a template, de-duplicated, in first-seen order. */
function extractFields(template) {
  const out = [];
  const seen = new Set();
  let m;
  FIELD_RE.lastIndex = 0;
  while ((m = FIELD_RE.exec(String(template || ''))) !== null) {
    if (!seen.has(m[1])) { seen.add(m[1]); out.push(m[1]); }
  }
  return out;
}

/**
 * Build the merge context for one applicant. Values are raw here; escaping
 * happens at render time so the same context can feed plain-text and HTML.
 */
function buildMergeContext(applicant, config = {}) {
  const name = String(applicant.name || '').trim();
  const first = name.split(' ')[0] || name;
  return {
    name,
    first_name: first,
    email: applicant.email || '',
    job_role: applicant.job_role || '',
    category: applicant.category || '',
    applicant_id: applicant.applicant_id || '',
    company_name: config.company_name || '',
    hr_name: config.hr_name || '',
    hr_signature: config.hr_signature || '',
    // V2 fields render as empty in V1 rather than blowing up shared templates.
    match_percent: applicant.match_percent == null ? '' : String(applicant.match_percent),
  };
}

/**
 * Render a template. `allowHtmlFields` names context keys whose value is
 * trusted HTML (the signature); everything else is escaped.
 *
 * @returns {{html: string, unresolved: string[], used: string[]}}
 */
function render(template, context, { escape = true, allowHtmlFields = ['hr_signature'] } = {}) {
  const src = String(template == null ? '' : template);
  const used = [];
  const unresolved = [];
  const allow = new Set(allowHtmlFields);

  const html = src.replace(FIELD_RE, (match, field) => {
    const value = context ? context[field] : undefined;
    if (value === undefined || value === null || String(value).trim() === '') {
      unresolved.push(field);
      return match; // leave it visible so validation can catch it
    }
    used.push(field);
    return escape && !allow.has(field) ? escapeHtml(value) : String(value);
  });

  return { html, unresolved: [...new Set(unresolved)], used: [...new Set(used)] };
}

/**
 * Cheap structural check for generated/uploaded HTML: balanced tags and no
 * script/iframe. Not a full parser — it catches the failure modes an LLM or a
 * hand-pasted template actually produces.
 */
function validateHtml(html) {
  const problems = [];
  const src = String(html == null ? '' : html);

  if (!src.trim()) problems.push('Template body is empty.');
  if (/<script\b/i.test(src)) problems.push('Contains a <script> tag — not allowed in email.');
  if (/<iframe\b/i.test(src)) problems.push('Contains an <iframe> tag — not allowed in email.');
  if (/\son[a-z]+\s*=/i.test(src)) problems.push('Contains an inline event handler (onclick=…) — not allowed in email.');

  const stack = [];
  const tagRe = /<\/?([a-zA-Z0-9!-]+)[^>]*?(\/?)>/g;
  let m;
  while ((m = tagRe.exec(src)) !== null) {
    const raw = m[0];
    const tag = m[1].toLowerCase();
    const selfClosing = m[2] === '/';
    if (VOID_TAGS.has(tag) || selfClosing || raw.startsWith('<!')) continue;
    if (raw.startsWith('</')) {
      const open = stack.pop();
      if (open !== tag) {
        problems.push(open ? `Mismatched tag: </${tag}> closes <${open}>.` : `Stray closing tag </${tag}>.`);
        break; // one structural report is enough; the rest cascade
      }
    } else {
      stack.push(tag);
    }
  }
  if (stack.length) problems.push(`Unclosed tag(s): ${[...new Set(stack)].map((t) => `<${t}>`).join(', ')}.`);

  return { ok: problems.length === 0, problems };
}

/**
 * Pick the best template for an applicant.
 *
 * Specificity wins: an exact role+category match beats role-only, which beats
 * the default. Returns the chosen template plus a warning when it had to fall
 * back, so the row records that it used a generic email.
 */
function selectTemplate(templates, { job_role, category, stage = 'outreach' } = {}) {
  const active = (templates || []).filter((t) => truthy(t.is_active));
  if (!active.length) {
    throw new AppError('E-MAIL-TEMPLATE', 'No active templates exist. Create one in the dashboard before drafting.', {});
  }

  const eq = (a, b) => String(a || '').trim().toLowerCase() === String(b || '').trim().toLowerCase();
  const stageMatches = active.filter((t) => !t.stage || eq(t.stage, stage));
  const pool = stageMatches.length ? stageMatches : active;

  const scored = pool.map((t) => {
    let score = 0;
    if (t.job_role && eq(t.job_role, job_role)) score += 4;
    else if (t.job_role) score -= 10; // wrong role is disqualifying, not neutral
    if (t.category && eq(t.category, category)) score += 2;
    else if (t.category) score -= 5;
    if (truthy(t.is_default)) score += 1;
    return { template: t, score };
  }).sort((a, b) => b.score - a.score);

  const best = scored[0];
  if (!best || best.score < 0) {
    const fallback = pool.find((t) => truthy(t.is_default));
    if (!fallback) {
      throw new AppError('E-MAIL-TEMPLATE', `No template matches role "${job_role}" and no default template is set.`, { job_role, category });
    }
    return { template: fallback, warning: 'W-TEMPLATE-DEFAULT' };
  }
  const usedDefault = best.score <= 1 && truthy(best.template.is_default);
  return { template: best.template, warning: usedDefault ? 'W-TEMPLATE-DEFAULT' : null };
}

/**
 * Full render + gate. Throws E-MAIL-TEMPLATE when anything would produce a
 * broken email, so callers cannot accidentally proceed.
 *
 * `extras` carries generated values that are not applicant columns — chiefly
 * `ai_body`. Those are trusted HTML because they have already passed
 * checkDraftSchema, so they render unescaped; the final validateHtml pass below
 * is still the backstop.
 */
function renderEmail({ template, applicant, config, extras = {} }) {
  const ctx = { ...buildMergeContext(applicant, config), ...extras };
  const allowHtmlFields = ['hr_signature', ...Object.keys(extras)];
  const subject = render(template.subject || '', ctx, { escape: false });
  const body = render(template.html || '', ctx, { escape: true, allowHtmlFields });

  const unresolved = [...new Set([...subject.unresolved, ...body.unresolved])];
  if (unresolved.length) {
    throw new AppError(
      'E-MAIL-TEMPLATE',
      `Unresolved merge field(s): ${unresolved.map((f) => `{{${f}}}`).join(', ')}.`,
      { unresolved, template_id: template.template_id }
    );
  }

  const structure = validateHtml(body.html);
  if (!structure.ok) {
    throw new AppError('E-MAIL-TEMPLATE', `Template HTML is invalid: ${structure.problems.join(' ')}`, { template_id: template.template_id });
  }
  if (!subject.html.trim()) {
    throw new AppError('E-MAIL-TEMPLATE', 'Rendered subject is empty.', { template_id: template.template_id });
  }

  return { subject: subject.html.trim(), html: body.html, template_id: template.template_id };
}

/** Sheets round-trips booleans as strings; treat them consistently everywhere. */
function truthy(v) {
  if (typeof v === 'boolean') return v;
  return ['true', 'yes', '1', 'y', 'x'].includes(String(v == null ? '' : v).trim().toLowerCase());
}

// ===== lib/ai-router.js =====

/**
 * The AI layer: one entry point for every model call in the system.
 *
 * Responsibilities, in order of importance:
 *   1. Never let a quota error corrupt a row. Exhaustion parks; it does not fail.
 *   2. Fail over Groq -> Gemini on transient errors, and record that it happened
 *      (W-AI-FAILOVER) so degradation is never silent.
 *   3. Enforce the token budget *before* dispatch, so we do not discover the
 *      limit by being rejected.
 *
 * All I/O is injected (`http`, `sleep`, `now`) so this is unit-testable with no
 * network and no real clock. See tests/ai-router.test.mjs.
 */

/**
 * Free-tier limits. PLACEHOLDERS — verify in the Groq / Google AI consoles and
 * override via the Quota tab. The router also self-corrects from live
 * x-ratelimit-* response headers, so a stale number here degrades gracefully.
 */
const MODELS = {
  'groq:llama-3.1-8b-instant':     { provider: 'groq',   model: 'llama-3.1-8b-instant',     rpm: 30, rpd: 14400, tpm: 6000,    tpd: 500000 },
  'groq:llama-3.3-70b-versatile':  { provider: 'groq',   model: 'llama-3.3-70b-versatile',  rpm: 30, rpd: 1000,  tpm: 12000,   tpd: 100000 },
  'gemini:gemini-2.0-flash':       { provider: 'gemini', model: 'gemini-2.0-flash',         rpm: 15, rpd: 1500,  tpm: 1000000, tpd: Infinity },
};

/** Ordered failover chains per task. First entry is primary. */
const ROUTES = {
  draft_email:      ['groq:llama-3.3-70b-versatile', 'gemini:gemini-2.0-flash'],
  generate_template:['groq:llama-3.3-70b-versatile', 'gemini:gemini-2.0-flash'],
  classify_reply:   ['groq:llama-3.1-8b-instant', 'gemini:gemini-2.0-flash'],
  // V2
  resume_markdown:  ['groq:llama-3.1-8b-instant', 'gemini:gemini-2.0-flash'],
  score_resume:     ['groq:llama-3.3-70b-versatile', 'gemini:gemini-2.0-flash', 'groq:llama-3.1-8b-instant'],
};

/**
 * ~4 characters per token. Crude, but it only needs to be right enough to
 * reserve budget; actual usage from the response reconciles the bucket.
 */
function estimateTokens(text) {
  if (!text) return 0;
  return Math.ceil(String(text).length / 4);
}

/** Models emit JSON wrapped in prose or ```json fences more often than not. */
function extractJson(raw) {
  const text = String(raw == null ? '' : raw).trim();
  if (!text) return null;
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidates = [fenced ? fenced[1] : null, text].filter(Boolean);
  for (const c of candidates) {
    try { return JSON.parse(c.trim()); } catch (_e) { /* try next */ }
  }
  // Last resort: the outermost balanced {...} or [...] span.
  const start = text.search(/[{[]/);
  if (start === -1) return null;
  const open = text[start];
  const close = open === '{' ? '}' : ']';
  let depth = 0, inStr = false, esc = false;
  for (let i = start; i < text.length; i++) {
    const ch = text[i];
    if (esc) { esc = false; continue; }
    if (ch === '\\') { esc = true; continue; }
    if (ch === '"') { inStr = !inStr; continue; }
    if (inStr) continue;
    if (ch === open) depth++;
    else if (ch === close && --depth === 0) {
      try { return JSON.parse(text.slice(start, i + 1)); } catch (_e) { return null; }
    }
  }
  return null;
}

/**
 * Token bucket per model, persisted to the Quota tab so it survives restarts.
 * Windows are wall-clock: minute buckets reset on the minute, day buckets at
 * UTC midnight, matching how the providers actually meter.
 */
class QuotaLedger {
  constructor(state = {}, nowFn = () => Date.now()) {
    this.now = nowFn;
    this.state = {};
    for (const [key, v] of Object.entries(state)) this.state[key] = { ...v };
  }

  _bucket(key) {
    const t = this.now();
    const minute = Math.floor(t / 60000);
    const day = Math.floor(t / 86400000);
    let b = this.state[key];
    if (!b) b = this.state[key] = { minute, day, rpm: 0, tpm: 0, rpd: 0, tpd: 0 };
    if (b.minute !== minute) { b.minute = minute; b.rpm = 0; b.tpm = 0; }
    if (b.day !== day) { b.day = day; b.rpd = 0; b.tpd = 0; }
    return b;
  }

  /**
   * @returns {{ok: true} | {ok: false, reason: 'rpm'|'tpm'|'rpd'|'tpd', waitMs: number}}
   */
  check(key, estTokens, limits) {
    const l = limits || MODELS[key];
    if (!l) return { ok: true };
    const b = this._bucket(key);
    const t = this.now();
    const msToNextMinute = 60000 - (t % 60000);
    const msToNextDay = 86400000 - (t % 86400000);

    if (b.rpd + 1 > l.rpd) return { ok: false, reason: 'rpd', waitMs: msToNextDay };
    if (b.tpd + estTokens > l.tpd) return { ok: false, reason: 'tpd', waitMs: msToNextDay };
    if (b.rpm + 1 > l.rpm) return { ok: false, reason: 'rpm', waitMs: msToNextMinute };
    if (b.tpm + estTokens > l.tpm) return { ok: false, reason: 'tpm', waitMs: msToNextMinute };
    return { ok: true };
  }

  /** Reserve before dispatch. */
  reserve(key, estTokens) {
    const b = this._bucket(key);
    b.rpm += 1; b.rpd += 1; b.tpm += estTokens; b.tpd += estTokens;
    return b;
  }

  /** Reconcile the estimate against what the provider actually charged. */
  settle(key, estTokens, actualTokens) {
    const b = this._bucket(key);
    const delta = (actualTokens || 0) - estTokens;
    b.tpm = Math.max(0, b.tpm + delta);
    b.tpd = Math.max(0, b.tpd + delta);
    return b;
  }

  /** Trust the provider's own accounting when it sends headers. */
  applyHeaders(key, headers) {
    if (!headers) return;
    const get = (n) => headers[n] ?? headers[n.toLowerCase()] ?? headers[n.toUpperCase()];
    const remTokens = Number(get('x-ratelimit-remaining-tokens'));
    const limTokens = Number(get('x-ratelimit-limit-tokens'));
    if (Number.isFinite(remTokens) && Number.isFinite(limTokens) && limTokens > 0) {
      this._bucket(key).tpm = Math.max(0, limTokens - remTokens);
    }
    const remReq = Number(get('x-ratelimit-remaining-requests'));
    const limReq = Number(get('x-ratelimit-limit-requests'));
    if (Number.isFinite(remReq) && Number.isFinite(limReq) && limReq > 0) {
      this._bucket(key).rpm = Math.max(0, limReq - remReq);
    }
  }

  snapshot() { return JSON.parse(JSON.stringify(this.state)); }

  /**
   * How many more items of `tokensPerItem` fit today, and how long they take.
   * This is what the dashboard's ETA panel renders.
   */
  forecast(key, tokensPerItem, limits) {
    const l = limits || MODELS[key];
    if (!l) return { remainingToday: Infinity, itemsPerMinute: Infinity, etaMinutes: 0 };
    const b = this._bucket(key);
    const remainingToday = Math.max(0, Math.floor(Math.min(
      (l.tpd - b.tpd) / tokensPerItem,
      l.rpd - b.rpd
    )));
    const itemsPerMinute = Math.min(l.tpm / tokensPerItem, l.rpm);
    return { remainingToday, itemsPerMinute, etaMinutes: (n) => n / itemsPerMinute };
  }
}

/** Exponential backoff with full jitter, so parallel workers do not resonate. */
function backoffMs(attempt, base = 2000, cap = 16000, rand = Math.random) {
  const exp = Math.min(cap, base * Math.pow(2, attempt));
  return Math.floor(exp / 2 + rand() * (exp / 2));
}

function buildGroqRequest({ model, system, user, json, temperature, maxTokens, apiKey }) {
  const messages = [];
  if (system) messages.push({ role: 'system', content: system });
  messages.push({ role: 'user', content: user });
  return {
    method: 'POST',
    url: 'https://api.groq.com/openai/v1/chat/completions',
    headers: { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
    body: {
      model,
      messages,
      temperature: temperature ?? 0.4,
      max_tokens: maxTokens ?? 2048,
      ...(json ? { response_format: { type: 'json_object' } } : {}),
    },
  };
}

function buildGeminiRequest({ model, system, user, json, temperature, maxTokens, apiKey }) {
  return {
    method: 'POST',
    url: `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${encodeURIComponent(apiKey)}`,
    headers: { 'Content-Type': 'application/json' },
    body: {
      contents: [{ role: 'user', parts: [{ text: user }] }],
      ...(system ? { systemInstruction: { parts: [{ text: system }] } } : {}),
      generationConfig: {
        temperature: temperature ?? 0.4,
        maxOutputTokens: maxTokens ?? 2048,
        ...(json ? { responseMimeType: 'application/json' } : {}),
      },
    },
  };
}

function parseGroqResponse(body) {
  const choice = body && body.choices && body.choices[0];
  const text = choice && choice.message ? choice.message.content : '';
  const usage = (body && body.usage) || {};
  return { text: text || '', tokens: usage.total_tokens || 0, finish: choice ? choice.finish_reason : '' };
}

function parseGeminiResponse(body) {
  const cand = body && body.candidates && body.candidates[0];
  if (cand && cand.finishReason === 'SAFETY') {
    throw new AppError('E-LLM-REFUSAL', 'Gemini blocked the response on safety grounds.', {});
  }
  const parts = cand && cand.content && cand.content.parts ? cand.content.parts : [];
  const text = parts.map((p) => p.text || '').join('');
  const usage = (body && body.usageMetadata) || {};
  return { text: text || '', tokens: usage.totalTokenCount || 0, finish: cand ? cand.finishReason : '' };
}

class AiRouter {
  /**
   * @param {object} opts
   * @param {(req: object) => Promise<{status:number, body:any, headers:object}>} opts.http
   * @param {(ms:number)=>Promise<void>} [opts.sleep]
   * @param {object} opts.keys            { groq, gemini }
   * @param {QuotaLedger} [opts.ledger]
   * @param {object} [opts.routes]        override ROUTES
   * @param {object} [opts.limits]        override MODELS
   * @param {(msg:string, meta:object)=>void} [opts.log]
   */
  constructor(opts) {
    this.http = opts.http;
    this.sleep = opts.sleep || ((ms) => new Promise((r) => setTimeout(r, ms)));
    this.keys = opts.keys || {};
    this.ledger = opts.ledger || new QuotaLedger({}, opts.now);
    this.routes = opts.routes || ROUTES;
    this.limits = opts.limits || MODELS;
    this.log = opts.log || (() => {});
    this.maxAttemptsPerModel = opts.maxAttemptsPerModel ?? 3;
    this.rand = opts.rand || Math.random;
  }

  /**
   * Run one task through its failover chain.
   *
   * @returns {Promise<{text, json, model, provider, tokens, failedOver, warnings, attempts}>}
   * @throws  {AppError} E-QUOTA-ALL when every model is exhausted (park, retry later)
   */
  async complete({ task, system, user, json = false, temperature, maxTokens, schemaCheck }) {
    const chain = this.routes[task];
    if (!chain) throw new AppError('E-CONFIG-MISSING', `No model route configured for task "${task}".`, { task });

    const estTokens = estimateTokens(system) + estimateTokens(user) + (maxTokens ?? 2048);
    const warnings = [];
    const attempts = [];
    let parked = null;
    let lastError = null;
    // A skipped provider (no key, unknown model) must never mask a real failure
    // further up the chain — otherwise "Groq returned invalid JSON" gets
    // reported as "no Gemini key", and the operator debugs the wrong thing.
    let skipError = null;

    for (let ci = 0; ci < chain.length; ci++) {
      const key = chain[ci];
      const spec = this.limits[key];
      if (!spec) { skipError = skipError || new AppError('E-CONFIG-MISSING', `Unknown model "${key}".`, {}); continue; }

      const apiKey = this.keys[spec.provider];
      if (!apiKey) {
        skipError = skipError || new AppError('E-CONFIG-MISSING', `No API key configured for provider "${spec.provider}".`, { provider: spec.provider });
        attempts.push({ model: key, outcome: 'no-key' });
        continue;
      }

      // Budget gate: skip an exhausted model rather than earning a 429.
      const gate = this.ledger.check(key, estTokens, spec);
      if (!gate.ok) {
        parked = parked || gate;
        attempts.push({ model: key, outcome: `quota:${gate.reason}` });
        this.log('quota-skip', { model: key, reason: gate.reason, waitMs: gate.waitMs });
        continue;
      }

      for (let attempt = 0; attempt < this.maxAttemptsPerModel; attempt++) {
        try {
          const result = await this._callOnce({ key, spec, apiKey, system, user, json, temperature, maxTokens, estTokens });

          if (json) {
            const parsed = extractJson(result.text);
            if (parsed === null) {
              // One repair pass, then give up on this model.
              const repaired = await this._repairJson({ key, spec, apiKey, system, user, raw: result.text, temperature, maxTokens, estTokens });
              if (repaired === null) throw new AppError('E-LLM-SCHEMA', 'Model did not return valid JSON, including after a repair attempt.', { model: key });
              result.json = repaired;
            } else {
              result.json = parsed;
            }
            if (schemaCheck) {
              const verdict = schemaCheck(result.json);
              if (!verdict || verdict.ok !== true) {
                throw new AppError('E-LLM-SCHEMA', `Response failed schema check: ${(verdict && verdict.reason) || 'unknown'}.`, { model: key });
              }
            }
          }

          if (ci > 0) {
            warnings.push('W-AI-FAILOVER');
            this.log('failover', { from: chain[0], to: key, reason: lastError ? lastError.code : 'quota' });
          }
          attempts.push({ model: key, outcome: 'ok', tokens: result.tokens });
          return { ...result, model: spec.model, provider: spec.provider, routeKey: key, failedOver: ci > 0, warnings, attempts };
        } catch (err) {
          const appErr = err instanceof AppError ? err : new AppError('E-UNKNOWN', err && err.message ? err.message : String(err), {});
          lastError = appErr;
          attempts.push({ model: key, outcome: appErr.code, attempt });
          this.log('attempt-failed', { model: key, code: appErr.code, attempt });

          if (appErr.park) { parked = { ok: false, reason: appErr.code, waitMs: 60000 }; break; }
          if (appErr.code === 'E-LLM-AUTH' || appErr.code === 'E-LLM-SCHEMA' || appErr.code === 'E-LLM-REFUSAL') break; // next model
          if (!appErr.retryable) break;
          if (attempt < this.maxAttemptsPerModel - 1) {
            await this.sleep(appErr.retryAfterMs || backoffMs(attempt, 2000, 16000, this.rand));
          }
        }
      }
    }

    if (parked && !lastError) {
      throw new AppError('E-QUOTA-ALL', 'All configured models are out of budget for now. Work is parked and will resume automatically.', { attempts, waitMs: parked.waitMs });
    }
    // Preference order: a real attempt failure, then a config problem, then quota.
    const finalErr = lastError || skipError || new AppError('E-QUOTA-ALL', 'No model could serve this request.', { attempts });
    finalErr.details = { ...(finalErr.details || {}), attempts };
    throw finalErr;
  }

  async _callOnce({ key, spec, apiKey, system, user, json, temperature, maxTokens, estTokens }) {
    const build = spec.provider === 'groq' ? buildGroqRequest : buildGeminiRequest;
    const req = build({ model: spec.model, system, user, json, temperature, maxTokens, apiKey });

    this.ledger.reserve(key, estTokens);
    let res;
    try {
      res = await this.http(req);
    } catch (err) {
      if (/timeout|ETIMEDOUT|ESOCKETTIMEDOUT|aborted/i.test(String(err && err.message))) {
        throw new AppError('E-LLM-TIMEOUT', 'Model request timed out.', { model: key });
      }
      throw new AppError('E-LLM-SERVER', `Network failure calling ${spec.provider}: ${err && err.message}`, { model: key });
    }

    this.ledger.applyHeaders(key, res.headers);

    if (res.status < 200 || res.status >= 300) {
      const err = classifyProviderHttp(res.status, res.body);
      const retryAfter = res.headers && (res.headers['retry-after'] || res.headers['Retry-After']);
      if (retryAfter) err.retryAfterMs = Math.min(60000, Number(retryAfter) * 1000 || 0);
      throw err;
    }

    const parsed = spec.provider === 'groq' ? parseGroqResponse(res.body) : parseGeminiResponse(res.body);
    if (!parsed.text || !parsed.text.trim()) throw new AppError('E-LLM-EMPTY', 'Model returned an empty response.', { model: key });

    this.ledger.settle(key, estTokens, parsed.tokens);
    return { text: parsed.text, tokens: parsed.tokens, finish: parsed.finish };
  }

  async _repairJson({ key, spec, apiKey, system, user, raw, temperature, maxTokens, estTokens }) {
    try {
      const repairUser = [
        'Your previous response was not valid JSON. Return the SAME content as a single valid JSON object.',
        'Output JSON only — no prose, no markdown fences.',
        '',
        '--- previous response ---',
        String(raw).slice(0, 4000),
      ].join('\n');
      const res = await this._callOnce({ key, spec, apiKey, system, user: repairUser, json: true, temperature: 0, maxTokens, estTokens });
      return extractJson(res.text);
    } catch (_e) {
      return null;
    }
  }
}

// ===== lib/pipeline.js =====

/**
 * Per-workflow decision logic, kept pure so every rule is unit-testable.
 *
 * The n8n Code nodes are deliberately thin wrappers around these functions: I/O
 * in the node, judgement in here.
 */





/**
 * A template opts into AI personalisation by containing {{ai_body}}.
 * Templates without it render deterministically and cost zero tokens — which is
 * how HR keeps the quota for the emails that actually need it.
 */
const AI_FIELD = 'ai_body';
function usesAi(template) {
  return extractFields(String(template && template.html || '')).includes(AI_FIELD)
      || extractFields(String(template && template.subject || '')).includes(AI_FIELD);
}

// --- WF-01 Intake -----------------------------------------------------------

/**
 * @returns {{rows: object[], errors: object[], stats: object}}
 *   `rows` are ready to write back (valid rows AND blocked rows — a blocked row
 *   must still land in the sheet with its reason, never be dropped).
 */
function planIntake({ rows, roles, categories, correlationId, now = nowIso(), idFactory = makeApplicantId }) {
  const seen = new Set();
  // Existing, already-processed rows seed the dedupe set.
  for (const r of rows || []) {
    if (r.applicant_id && r.email && r.job_role && r.status !== STATUS.BLOCKED) {
      seen.add(dedupeKey(r.email, r.job_role));
    }
  }

  const out = [];
  const errors = [];
  let processed = 0;

  for (const raw of rows || []) {
    // Only untouched rows are candidates: anything with an id and a stage has
    // already been through here.
    if (raw.applicant_id && raw.stage) continue;
    processed++;

    const result = validateIntake(raw, {
      roles, categories, seen, correlationId,
      applicantId: idFactory(new Date(now)),
      now,
    });

    if (result.ok) {
      seen.add(result.key);
      out.push({ ...raw, ...result.row, _row_number: raw._row_number });
    } else {
      const e = result.error;
      out.push({
        ...raw, ...result.row,
        error_code: e.code, error_message: e.message,
        _row_number: raw._row_number,
      });
      errors.push({ applicant_id: result.row.applicant_id, error: e, payload: { email: raw.email, job_role: raw.job_role } });
    }
  }

  return { rows: out, errors, stats: { scanned: (rows || []).length, processed, blocked: errors.length } };
}

// --- WF-02 Drafting ---------------------------------------------------------

/** Which applicants are eligible for a draft right now. */
function selectForDrafting({ applicants, ids = null, batchSize = 10, redraft = false }) {
  const wanted = ids && ids.length ? new Set(ids) : null;
  const eligible = (applicants || []).filter((a) => {
    if (!a.applicant_id) return false;
    if (wanted) return wanted.has(a.applicant_id);
    if (a.status === STATUS.BLOCKED) return false;
    if (redraft) return [STAGE.NEW, STAGE.DRAFTED, STAGE.FAILED, STAGE.SCORED, STAGE.SHORTLISTED].includes(a.stage);
    return a.stage === STAGE.NEW || (a.stage === STAGE.FAILED && !a.email_subject);
  });
  return eligible.slice(0, Math.max(1, batchSize));
}

/** The user-side prompt for personalising one email. */
function buildDraftPrompt({ applicant, template, config, promptVersion = 'draft-email.v1' }) {
  const lines = [
    `Company: ${config.company_name || 'the company'}`,
    `Candidate name: ${applicant.name}`,
    `Role applied for: ${applicant.job_role}`,
    applicant.category ? `Seniority/category: ${applicant.category}` : '',
    `Sender: ${config.hr_name || 'HR'}`,
    '',
    'Write the body of an outreach email to this candidate about their application.',
    '',
    'Return JSON only, exactly: {"subject": "...", "body_html": "..."}',
    'Rules for body_html:',
    '- 2 to 4 short paragraphs, wrapped in <p> tags.',
    '- Allowed tags: <p> <br> <strong> <em> <ul> <li> <a>. Nothing else.',
    '- Do not include a greeting line or a sign-off — the template supplies both.',
    '- Do not invent facts about the candidate, the salary, the interview date, or the process.',
    '- Do not use placeholders or merge fields of any kind.',
    `- Address the ${applicant.job_role} role specifically; a generic email is a failure.`,
  ].filter(Boolean);
  return { user: lines.join('\n'), promptVersion, template_id: template && template.template_id };
}

/** Structural gate on what the model returned, before it reaches a template. */
function checkDraftSchema(json) {
  if (!json || typeof json !== 'object') return { ok: false, reason: 'not an object' };
  if (typeof json.subject !== 'string' || !json.subject.trim()) return { ok: false, reason: 'missing subject' };
  if (typeof json.body_html !== 'string' || !json.body_html.trim()) return { ok: false, reason: 'missing body_html' };
  if (/\{\{|\}\}/.test(json.body_html + json.subject)) return { ok: false, reason: 'model emitted merge-field placeholders' };
  if (/<(script|iframe|style)\b/i.test(json.body_html)) return { ok: false, reason: 'disallowed tag in body_html' };
  if (json.body_html.length > 20000) return { ok: false, reason: 'body_html unreasonably long' };
  return { ok: true };
}

/**
 * Turn one applicant + one AI result into the draft columns.
 * `ai` is null for templates that do not use {{ai_body}}.
 */
function assembleDraft({ applicant, template, config, ai, correlationId, now = nowIso() }) {
  const mergeExtras = ai ? { ai_body: ai.body_html } : {};
  const effectiveTemplate = {
    ...template,
    subject: ai && ai.subject && usesAi(template) && String(template.subject || '').includes(`{{${AI_FIELD}}}`)
      ? ai.subject
      : template.subject,
  };

  const rendered = renderEmail({
    template: effectiveTemplate,
    applicant,
    config,
    extras: mergeExtras,
  });

  return {
    applicant_id: applicant.applicant_id,
    template_id: template.template_id,
    email_subject: rendered.subject,
    email_html: fitCell(rendered.html),
    stage: STAGE.DRAFTED,
    status: STATUS.OK,
    error_code: '',
    error_message: '',
    correlation_id: correlationId,
    updated_at: now,
  };
}

// --- WF-03 Sending ----------------------------------------------------------

/**
 * Decide what may actually be sent. This is the most safety-critical function
 * in V1: every rejection here is an email that would have embarrassed someone.
 */
function planSends({ applicants, ids, config, sentToday = 0, now = nowIso() }) {
  const wanted = ids && ids.length ? new Set(ids) : null;
  const cap = Number(config.send_daily_cap) || 400;
  const dryRun = truthy(config.dry_run);

  const approved = [];
  const rejected = [];
  let budget = Math.max(0, cap - sentToday);

  for (const a of applicants || []) {
    if (wanted && !wanted.has(a.applicant_id)) continue;

    const reject = (code, msg) => rejected.push({ applicant_id: a.applicant_id, error: new AppError(code, msg, {}) });

    if (a.stage !== STAGE.APPROVED) { reject('E-MAIL-NODRAFT', `Stage is "${a.stage || 'empty'}", not APPROVED. Approve the draft before sending.`); continue; }
    if (!canTransition(a.stage, STAGE.SENT)) { reject('E-MAIL-NODRAFT', `Illegal transition ${a.stage} -> SENT.`); continue; }
    if (!a.email_subject || !a.email_html) { reject('E-MAIL-NODRAFT', 'Row is APPROVED but has no draft body. Regenerate the draft.'); continue; }
    if (/\{\{[^}]+\}\}/.test(String(a.email_subject) + String(a.email_html))) { reject('E-MAIL-TEMPLATE', 'Draft still contains unresolved merge fields. Nothing was sent.'); continue; }
    if (!isValidEmail(a.email)) { reject('E-MAIL-BOUNCE', `"${a.email}" is not a deliverable address.`); continue; }
    if (a.email_status === 'sent') { reject('E-MAIL-NODRAFT', 'Already sent. Refusing to send a duplicate.'); continue; }
    if (budget <= 0) { reject('E-MAIL-LIMIT', `Daily send cap of ${cap} reached. Remaining sends resume tomorrow.`); continue; }

    budget--;
    approved.push({
      applicant_id: a.applicant_id,
      to: a.email,
      name: a.name,
      subject: a.email_subject,
      html: a.email_html,
      dry_run: dryRun,
      _row_number: a._row_number,
    });
  }

  return { approved, rejected, dryRun, capRemaining: budget, now };
}

/** Post-send row updates, from the Gmail node's result. */
function recordSend({ item, result, correlationId, now = nowIso() }) {
  const sent = !item.dry_run && result && !result.error;
  return {
    applicant: {
      applicant_id: item.applicant_id,
      stage: sent ? STAGE.SENT : STAGE.APPROVED,
      status: sent ? STATUS.OK : STATUS.PENDING,
      email_status: item.dry_run ? 'dry-run' : (sent ? 'sent' : 'failed'),
      sent_at: sent ? now : '',
      thread_id: (result && result.threadId) || '',
      message_id: (result && result.id) || '',
      error_code: sent || item.dry_run ? '' : 'E-MAIL-BOUNCE',
      error_message: sent || item.dry_run ? '' : String((result && result.error) || 'Send failed'),
      correlation_id: correlationId,
      updated_at: now,
    },
    log: {
      at: now,
      correlation_id: correlationId,
      applicant_id: item.applicant_id,
      to: item.to,
      subject: item.subject,
      provider: 'gmail',
      result: item.dry_run ? 'dry-run' : (sent ? 'sent' : 'failed'),
      provider_message_id: (result && result.id) || '',
      thread_id: (result && result.threadId) || '',
      dry_run: String(item.dry_run),
      error_code: sent || item.dry_run ? '' : 'E-MAIL-BOUNCE',
      error_message: sent || item.dry_run ? '' : String((result && result.error) || ''),
    },
  };
}

// --- WF-04 Replies ----------------------------------------------------------

/** Thread id is authoritative; from-address is the fallback for forwarded mail. */
function matchReply({ message, applicants }) {
  const threadId = message.threadId || message.thread_id || '';
  const from = String(message.from || '').toLowerCase();
  const fromEmail = (from.match(/[\w.+-]+@[\w-]+\.[\w.-]+/) || [''])[0];

  if (threadId) {
    const byThread = (applicants || []).find((a) => a.thread_id && a.thread_id === threadId);
    if (byThread) return { applicant: byThread, matchedBy: 'thread_id' };
  }
  if (fromEmail) {
    const byEmail = (applicants || [])
      .filter((a) => String(a.email || '').toLowerCase() === fromEmail && a.stage === STAGE.SENT)
      .sort((a, b) => String(b.sent_at || '').localeCompare(String(a.sent_at || '')));
    if (byEmail.length) return { applicant: byEmail[0], matchedBy: 'email' };
  }
  return { applicant: null, matchedBy: 'none' };
}

const REPLY_INTENTS = ['interested', 'declined', 'question', 'out_of_office', 'unclear'];

function buildReplyPrompt({ message }) {
  return [
    'Classify this reply from a job candidate.',
    '',
    'Return JSON only: {"intent": "...", "confidence": 0.0, "summary": "..."}',
    `intent must be one of: ${REPLY_INTENTS.join(', ')}.`,
    'confidence is 0.0-1.0. summary is one sentence, max 140 characters.',
    'If the message is ambiguous, say "unclear" with low confidence rather than guessing.',
    '',
    '--- reply ---',
    String(message.text || message.snippet || '').slice(0, 4000),
  ].join('\n');
}

function checkReplySchema(json) {
  if (!json || typeof json !== 'object') return { ok: false, reason: 'not an object' };
  if (!REPLY_INTENTS.includes(json.intent)) return { ok: false, reason: `intent "${json.intent}" not in the allowed set` };
  const c = Number(json.confidence);
  if (!Number.isFinite(c) || c < 0 || c > 1) return { ok: false, reason: 'confidence out of range' };
  return { ok: true };
}

/**
 * Low-confidence classifications are escalated, never acted on. The model
 * sorting the inbox is a convenience; it does not get to decide outcomes.
 */
function applyReply({ applicant, message, classification, config, now = nowIso() }) {
  const min = Number(config.reply_confidence_min ?? 0.7);
  const confident = Number(classification.confidence) >= min;
  const intent = confident ? classification.intent : 'unclear';
  const warnings = confident ? [] : ['W-REPLY-LOWCONF'];

  return {
    warnings,
    reply: {
      received_at: message.received_at || now,
      applicant_id: applicant.applicant_id,
      thread_id: message.threadId || applicant.thread_id || '',
      from: message.from || applicant.email,
      subject: message.subject || '',
      snippet: String(message.snippet || message.text || '').slice(0, 500),
      classified_intent: intent,
      confidence: Number(classification.confidence) || 0,
      model: classification.model || '',
      handled_by: '',
      handled_at: '',
    },
    applicant: {
      applicant_id: applicant.applicant_id,
      stage: STAGE.REPLIED,
      reply_state: confident ? intent : 'needs_human',
      updated_at: now,
    },
  };
}

// --- WF-05 Follow-ups -------------------------------------------------------

/** Candidates who were emailed, never replied, and are past the silence window. */
function planFollowups({ applicants, config, now = new Date() }) {
  const days = Number(config.followup_days) || 5;
  const cutoff = new Date(now.getTime() - days * 86400000);
  return (applicants || []).filter((a) => {
    if (a.stage !== STAGE.SENT) return false;
    if (a.reply_state && a.reply_state !== 'none') return false;
    if (!a.sent_at) return false;
    const sent = new Date(a.sent_at);
    return !Number.isNaN(sent.getTime()) && sent < cutoff;
  });
}

// ===== lib/runtime.js =====

/**
 * The seam between the pure engine and n8n's Code-node sandbox.
 *
 * Everything n8n-specific lives here so the rest of the library stays testable
 * with plain Node. `ctx` is the Code node's `this`.
 */


/**
 * HTTP adapter shaped for AiRouter.
 *
 * n8n's `this.helpers.httpRequest` is preferred (it respects proxy settings and
 * n8n's own timeouts), with `fetch` as a fallback for sandbox configurations
 * where helpers are not exposed. Non-2xx must come back as a value, not a
 * throw — the router classifies statuses itself.
 */
function makeHttp(ctx, { timeout = 60000 } = {}) {
  const helper = ctx && ctx.helpers && typeof ctx.helpers.httpRequest === 'function' ? ctx.helpers.httpRequest.bind(ctx.helpers) : null;

  return async function http(req) {
    if (helper) {
      const res = await helper({
        method: req.method,
        url: req.url,
        headers: req.headers,
        body: req.body,
        json: true,
        timeout,
        returnFullResponse: true,
        ignoreHttpStatusErrors: true,
      });
      return { status: res.statusCode || res.status || 200, body: res.body, headers: res.headers || {} };
    }

    if (typeof fetch !== 'function') {
      throw new AppError('E-CONFIG-MISSING', 'No HTTP transport available in this n8n Code node (neither this.helpers.httpRequest nor fetch).', {});
    }
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeout);
    try {
      const res = await fetch(req.url, {
        method: req.method,
        headers: req.headers,
        body: typeof req.body === 'string' ? req.body : JSON.stringify(req.body),
        signal: controller.signal,
      });
      const text = await res.text();
      let body;
      try { body = JSON.parse(text); } catch (_e) { body = text; }
      const headers = {};
      res.headers.forEach((v, k) => { headers[k.toLowerCase()] = v; });
      return { status: res.status, body, headers };
    } finally {
      clearTimeout(timer);
    }
  };
}

/** API keys from the n8n environment. Requires N8N_BLOCK_ENV_ACCESS_IN_NODE=false. */
function apiKeys(env) {
  const e = env || {};
  return { groq: e.GROQ_API_KEY || '', gemini: e.GEMINI_API_KEY || '' };
}

/** `$('Node').all()` -> plain row objects, tolerant of a missing/empty node. */
function rowsOf(items) {
  if (!items) return [];
  return items.map((i) => (i && i.json ? i.json : i)).filter(Boolean);
}

/** Wrap plain objects back into n8n items. */
function toItems(rows) {
  return (rows || []).map((json) => ({ json }));
}

/**
 * Standard envelope every workflow's terminal code node returns. The dashboard
 * reads exactly this shape, so a new workflow is legible without new UI.
 */
function envelope({ workflow, correlationId, trigger = 'manual', started, items_in = 0, ok = [], failed = [], warnings = [], notes = '' }) {
  return {
    ok: failed.length === 0,
    workflow,
    correlation_id: correlationId,
    trigger,
    started_at: started,
    finished_at: nowIso(),
    items_in,
    items_ok: ok.length,
    items_failed: failed.length,
    status: failed.length === 0 ? 'ok' : (ok.length ? 'partial' : 'failed'),
    warnings: [...new Set(warnings)],
    notes,
    results: ok,
    errors: failed,
  };
}

/** Row shape for the Errors tab. Payloads are PII-redacted by safeJson. */
function errorRow({ correlationId, applicantId = '', workflow, node = '', error, payload = {}, retryCount = 0 }) {
  const e = toAppError(error);
  return {
    at: nowIso(),
    correlation_id: correlationId,
    applicant_id: applicantId,
    workflow,
    node,
    error_code: e.code,
    error_message: e.message,
    severity: e.severity,
    retryable: String(e.retryable),
    hint: e.hint,
    payload_json: safeJson({ ...payload, details: e.details }),
    retry_count: retryCount,
    resolved: 'FALSE',
  };
}

/** Row shape for the RunLog tab. */
function runLogRow(env) {
  return {
    started_at: env.started_at,
    correlation_id: env.correlation_id,
    workflow: env.workflow,
    trigger: env.trigger,
    finished_at: env.finished_at,
    items_in: env.items_in,
    items_ok: env.items_ok,
    items_failed: env.items_failed,
    status: env.status,
    notes: [env.notes, env.warnings.length ? `warnings: ${env.warnings.join(',')}` : ''].filter(Boolean).join(' | '),
  };
}

/**
 * A workflow toggle that is OFF is a normal outcome, not an error: the run
 * ends immediately with a skipped envelope so the dashboard shows why nothing
 * happened.
 */
function skipped({ workflow, correlationId, reason, started }) {
  return { ...envelope({ workflow, correlationId, started }), ok: true, status: 'skipped', notes: reason };
}

function newCorrelationId(workflow) { return makeCorrelationId(workflow); }

// ===== nodes/wf02-draft.js =====

// @requires errors schema util intake template ai-router pipeline runtime
//
// WF-02 Draft generation. The only node in V1 that spends model quota.
//
// Two costs are deliberately avoided here:
//   - templates without {{ai_body}} never reach the model at all;
//   - the quota ledger is checked before dispatch, so an exhausted budget parks
//     the batch instead of burning retries on guaranteed 429s.

const started = nowIso();
const correlationId = newCorrelationId('WF-02');
const WORKFLOW = 'WF-02 Draft';

let env = {};
try { env = $env || {}; } catch (_e) { env = {}; }

const request = (() => {
  try { return $('Verify Request').first().json || {}; } catch (_e) { return {}; }
})();

// Quota survives restarts in n8n's own static store — no sheet round-trip on
// the hot path.
const store = $getWorkflowStaticData('global');
store.quota = store.quota || {};

const applicant_rows = [];
const error_rows = [];
const quota_rows = [];
const ok = [];
const failed = [];
const warnings = [];

try {
  const config = parseConfig(rowsOf($('Read Config').all()));
  if (!config.toggle_draft) {
    return [{ json: { ...skipped({ workflow: WORKFLOW, correlationId, started, reason: 'toggle_draft is OFF in the Config tab.' }), applicant_rows: [], error_rows: [], runlog_rows: [] } }];
  }

  const templates = rowsOf($('Read Templates').all());
  const applicants = rowsOf($('Read Applicants').all()).map((r) => ({ ...r, _row_number: r.row_number }));

  const selected = selectForDrafting({
    applicants,
    ids: Array.isArray(request.ids) ? request.ids : null,
    batchSize: Number(request.batch_size) || Number(config.batch_size) || 10,
    redraft: request.redraft === true,
  });

  const ledger = new QuotaLedger(store.quota);
  const router = new AiRouter({
    http: makeHttp(this, { timeout: 60000 }),
    keys: apiKeys(env),
    ledger,
    log: (msg, meta) => console.log(`[${correlationId}] ${msg}`, JSON.stringify(meta)),
  });

  for (const applicant of selected) {
    try {
      const picked = selectTemplate(templates, { job_role: applicant.job_role, category: applicant.category, stage: 'outreach' });
      if (picked.warning) warnings.push(picked.warning);

      let ai = null;
      if (usesAi(picked.template)) {
        const prompt = buildDraftPrompt({ applicant, template: picked.template, config });
        const res = await router.complete({
          task: 'draft_email',
          system: 'You write concise, warm, factual recruiting emails. You never invent details. You return JSON only.',
          user: prompt.user,
          json: true,
          temperature: 0.5,
          maxTokens: 1200,
          schemaCheck: checkDraftSchema,
        });
        ai = res.json;
        if (res.failedOver) warnings.push('W-AI-FAILOVER');
        warnings.push(...(res.warnings || []));
      }

      const draft = assembleDraft({ applicant, template: picked.template, config, ai, correlationId, now: nowIso() });
      applicant_rows.push({ ...draft, row_number: applicant._row_number });
      ok.push({ applicant_id: applicant.applicant_id, ai: Boolean(ai) });
    } catch (err) {
      // Item-level isolation: one bad applicant never aborts the batch.
      const e = toAppError(err);
      failed.push({ applicant_id: applicant.applicant_id, code: e.code, message: e.message });
      error_rows.push(errorRow({
        correlationId, applicantId: applicant.applicant_id, workflow: WORKFLOW, node: 'Generate Drafts',
        error: e, payload: { job_role: applicant.job_role, category: applicant.category },
      }));
      applicant_rows.push({
        applicant_id: applicant.applicant_id,
        row_number: applicant._row_number,
        stage: e.park ? applicant.stage : 'FAILED',
        status: e.park ? 'pending' : 'failed',
        error_code: e.code,
        error_message: e.message,
        correlation_id: correlationId,
        updated_at: nowIso(),
      });
      // Every provider exhausted: stop the batch rather than failing the rest
      // one by one. The remaining rows stay NEW and get picked up next run.
      if (e.code === 'E-QUOTA-ALL') break;
    }
  }

  store.quota = ledger.snapshot();
  const now = nowIso();
  for (const [key, b] of Object.entries(store.quota)) {
    const limits = MODELS[key] || {};
    const [provider, ...rest] = key.split(':');
    quota_rows.push({
      provider, model: rest.join(':'), window: 'day',
      requests_used: b.rpd, tokens_used: b.tpd,
      requests_limit: limits.rpd === Infinity ? '' : limits.rpd,
      tokens_limit: limits.tpd === Infinity ? '' : limits.tpd,
      window_reset_at: new Date(Math.ceil(Date.now() / 86400000) * 86400000).toISOString(),
      updated_at: now,
    });
  }

  const env0 = envelope({
    workflow: WORKFLOW, correlationId, trigger: request.trigger || 'webhook', started,
    items_in: selected.length, ok, failed, warnings,
    notes: `${ok.length} drafted, ${failed.length} failed`,
  });
  return [{ json: { ...env0, applicant_rows, error_rows, quota_rows, runlog_rows: [runLogRow(env0)] } }];
} catch (err) {
  const e = toAppError(err);
  const env0 = envelope({ workflow: WORKFLOW, correlationId, trigger: 'webhook', started, failed: [{ code: e.code, message: e.message }], notes: e.hint });
  return [{
    json: {
      ...env0,
      applicant_rows,
      error_rows: [...error_rows, errorRow({ correlationId, workflow: WORKFLOW, node: 'Generate Drafts', error: e })],
      quota_rows,
      runlog_rows: [runLogRow(env0)],
    },
  }];
}

